import type { DeliveryStatus, RecruitmentMessageStatus, RecruitmentMessageType } from '~/client';
import type { BadgeVariants } from '~/components/ui/badge';
import { getMessageStatus } from '~/constants/recruitment/messageStatusConfig';

interface MessageTypeEntry {
  label: string;
  variant: BadgeVariants;
}

export const messageTypeConfig: Record<RecruitmentMessageType, MessageTypeEntry> = {
  general: { label: 'General', variant: 'info' },
  project: { label: 'Project', variant: 'info' },
};

const defaultEntry: MessageTypeEntry = { label: '', variant: 'default' };

export function getMessageType(type: RecruitmentMessageType): MessageTypeEntry {
  return messageTypeConfig[type] ?? { ...defaultEntry, label: snakeCaseToCapitalizedCase(type) };
}

export const messageTypeOptions: SelectItem<RecruitmentMessageType>[] = Object.entries(messageTypeConfig).map(
  ([value, { label }]) => ({ name: label, value: value as RecruitmentMessageType })
);

// Authored timeline order - the union members come in alphabetical order, the filter wants lifecycle order.
const effectiveStatusOrder: (DeliveryStatus | RecruitmentMessageStatus)[] = [
  'pending_generation',
  'generating',
  'pending_scheduling',
  'scheduled',
  'sending',
  'sent',
  'delivered',
  'opened',
  'opened_unique',
  'clicked',
  'clicked_unique',
  'deferred',
  'soft_bounced',
  'hard_bounced',
  'spam_complaint',
  'unsubscribed',
  'failed',
  'skipped',
];

export const effectiveStatusOptions: SelectItem<DeliveryStatus | RecruitmentMessageStatus>[] = effectiveStatusOrder.map(
  (value) => ({ name: getMessageStatus(value).label, value })
);
