import type { DeliveryStatus, RecruitmentMessageStatus } from '~/client';
import type { BadgeVariants } from '~/components/ui/badge/index';

type InteractionStatus = DeliveryStatus | RecruitmentMessageStatus;

interface MessageStatusEntry {
  label: string;
  variant: BadgeVariants;
  dotColor: string;
}

export const messageStatusConfig: Record<InteractionStatus, MessageStatusEntry> = {
  pending_generation: { label: 'Pending Generation', variant: 'default', dotColor: 'bg-gray-400' },
  sent: { label: 'Sent', variant: 'success', dotColor: 'bg-green-500' },
  delivered: { label: 'Delivered', variant: 'success', dotColor: 'bg-green-500' },
  pending_scheduling: { label: 'Pending Scheduling', variant: 'warning', dotColor: 'bg-yellow-500' },
  scheduled: { label: 'Scheduled', variant: 'warning', dotColor: 'bg-yellow-500' },
  sending: { label: 'Sending', variant: 'info', dotColor: 'bg-blue-500' },
  failed: { label: 'Failed', variant: 'destructive', dotColor: 'bg-red-500' },
  skipped: { label: 'Skipped', variant: 'default', dotColor: 'bg-gray-400' },
  hard_bounced: { label: 'Hard Bounced', variant: 'destructive', dotColor: 'bg-red-500' },
  soft_bounced: { label: 'Soft Bounced', variant: 'warning', dotColor: 'bg-orange-400' },
  generating: { label: 'Generating', variant: 'info', dotColor: 'bg-blue-500' },
  opened: { label: 'Opened', variant: 'success', dotColor: 'bg-green-400' },
  opened_unique: { label: 'Opened Unique', variant: 'success', dotColor: 'bg-green-400' },
  clicked: { label: 'Clicked', variant: 'success', dotColor: 'bg-green-400' },
  clicked_unique: { label: 'Clicked Unique', variant: 'success', dotColor: 'bg-green-400' },
  spam_complaint: { label: 'Spam Complaint', variant: 'destructive', dotColor: 'bg-red-500' },
  unsubscribed: { label: 'Unsubscribed', variant: 'destructive', dotColor: 'bg-red-400' },
  deferred: { label: 'Deferred', variant: 'warning', dotColor: 'bg-orange-400' },
};

const defaultStatus: MessageStatusEntry = { label: '', variant: 'default', dotColor: 'bg-gray-400' };

export function getMessageStatus(status: InteractionStatus): MessageStatusEntry {
  return messageStatusConfig[status] ?? { ...defaultStatus, label: snakeCaseToCapitalizedCase(status) };
}
